button[type="submit"]:hover {
  background-color: var(--accent-hover);
}

button[type="submit"]:focus-visible {
  outline: 2px solid var(--focus-ring);
  outline-offset: 2px;
}

.status-message {
  margin-top: 1.5rem;
  padding: 1rem;
  border-radius: 6px;
  font-weight: 500;
  text-align: center;
}

.status-message.success {
  background-color: var(--success-bg);
